country_event = {
	id = germany_mengele.10
	title = germany_mengele.10.t
	desc = germany_mengele.10.d
	picture = GFX_report_event_generic_biowarfare
	is_triggered_only = yes

	immediate = {
		if = {
			limit = { germany_mengele_program_active = yes }
			set_country_flag = germany_mengele_report_without_names
			germany_mengele_register_experiment_deaths = yes
			set_temp_variable = { mengele_chaos_change = constant:germany_mengele_chaos.reports }
			set_temp_variable = { mengele_chaos_reason = constant:chaos_meter_history_reason.special.mengele_reports }
			germany_mengele_add_chaos = yes
			set_temp_variable = { mengele_condemnation_add = constant:germany_mengele_condemnation.reports }
			germany_mengele_add_condemnation = yes
			set_temp_variable = { mengele_stage_value = constant:germany_mengele_stage.reports }
			germany_mengele_record_stage = yes
		}
	}

	option = {
		name = germany_mengele.10.a
		trigger = { germany_mengele_program_active = yes }
		ai_chance = { base = 15 }
		set_temp_variable = { mengele_autonomy_delta = constant:germany_mengele_autonomy.reports_without_names_continue }
		germany_mengele_add_autonomy = yes
		country_event = { id = germany_mengele.11 days = 95 random_days = 45 }
	}

	option = {
		name = germany_mengele.10.b
		trigger = { germany_mengele_program_active = yes }
		ai_chance = { base = 65 }
		set_country_flag = germany_mengele_berlin_restrictions_issued
		set_temp_variable = { mengele_autonomy_delta = constant:germany_mengele_autonomy.reports_without_names_restrict }
		germany_mengele_add_autonomy = yes
		add_political_power = constant:germany_mengele_decision_value.complete_records_political_power
		country_event = { id = germany_mengele.11 days = 120 random_days = 45 }
	}

	option = {
		name = germany_mengele.10.c
		trigger = { germany_mengele_program_active = yes }
		ai_chance = { base = 20 }
		if = {
			limit = { NOT = { has_active_mission = germany_auschwitz_military_review_mission } }
			camp_rework_germany_start_military_review_mission = yes
		}
		set_temp_variable = { mengele_autonomy_delta = constant:germany_mengele_autonomy.military_review_reduction }
		germany_mengele_add_autonomy = yes
		country_event = { id = germany_mengele.11 days = 150 random_days = 45 }
	}

	option = {
		name = germany_mengele.10.closed
		trigger = { NOT = { germany_mengele_program_active = yes } }
		ai_chance = { base = 100 }
	}
}
